    ('櫻田山神社', null, '宮城県', '栗原市', 38.7958176, 140.9848698, 'C', '神社仏閣', '櫻田山神社（さくらださんじんじゃ）は、宮城県栗原市栗駒桜田にある神社。正式名称は山神社（さんじんじゃ）であるが、地区名の桜田を冠した「櫻田山神社」で一般に呼ばれる。'),
    ('多賀城跡', null, '宮城県', '多賀城市', 38.3069193, 140.988775, 'A', 'その他', '多賀城（たがじょう）は、宮城県多賀城市にあった古代城柵。'),
    ('仙台城', null, '宮城県', '仙台市', 38.2526678, 140.8562825, 'A', 'その他', '仙台城（せんだいじょう、旧字体: 仙臺城）は、宮城県仙台市青葉区（陸奥国宮城郡）の青葉山にあった日本の城（平山城）。'),
    ('北上川', null, '宮城県', null, 38.6098577, 141.3694878, 'B', 'その他', '北上川（きたかみがわ）は、岩手県中央部を北から南に流れ宮城県東部の石巻市で追波湾に注ぐ一級河川。'),
    ('田代島', null, '宮城県', '石巻市', 38.2966042, 141.4147474, 'B', '自然', '田代島（たしろじま）は、牡鹿半島の西側にある島である。'),
    ('仙台スタジアム', null, '宮城県', '仙台市', 38.3193218, 140.8826955, 'B', 'その他', '仙台スタジアム（せんだいスタジアム）は、宮城県仙台市泉区の七北田公園内に所在するサッカー・ラグビー・アメリカンフットボールの専用球技場。'),
    ('白石城', null, '宮城県', '白石市', 38.0021221, 140.6174429, 'B', 'その他', '白石城（しろいしじょう）は、宮城県白石市（陸奥国刈田郡白石）にあった日本の城（平山城）。'),
    ('スポーツランドSUGO', null, '宮城県', '村田町', 38.1415702, 140.7776339, 'B', 'その他', 'スポーツランドSUGO（スポーツランドすごう）は、宮城県柴田郡村田町菅生にある総合モータースポーツ施設である。'),
    ('八木山ベニーランド', null, '宮城県', '仙台市', 38.2470388, 140.8486243, 'B', '自然', '八木山ベニーランド（やぎやまベニーランド）は、宮城県仙台市太白区の八木山にある遊園地である。'),
    ('蔵王連峰', null, '宮城県', null, 38.127749, 140.4481979, 'B', 'その他', '蔵王連峰（ざおうれんぽう）は、東北地方の中央を南北に連なる奥羽山脈の中にあって、宮城県と山形県の両県南部の県境に位置する連峰。'),
    ('女川原子力発電所', null, '宮城県', '女川町', 38.3992474, 141.5022589, 'B', 'その他', '女川原子力発電所（おながわげんしりょくはつでんしょ）は、宮城県牡鹿郡女川町と石巻市にまたがる東北電力の原子力発電所である。'),
    ('せんだいメディアテーク', null, '宮城県', '仙台市', 38.2655471, 140.8654738, 'B', 'その他', 'せんだいメディアテーク（英: sendai mediatheque）は、宮城県仙台市青葉区にある公共施設である。'),
    ('瑞鳳殿', null, '宮城県', '仙台市', 38.2525647, 140.8666148, 'B', 'その他', '瑞鳳殿（ずいほうでん）は、宮城県仙台市青葉区霊屋下にある仙台藩祖伊達政宗の霊廟である。'),
    ('仙台うみの杜水族館', null, '宮城県', '仙台市', 38.2707423, 140.9805884, 'B', '美術館博物館', '仙台うみの杜水族館（せんだいうみのもりすいぞくかん）は、宮城県仙台市宮城野区の高砂中央公園に所在する水族館である。'),
    ('栗駒山', null, '宮城県', null, 38.9609164, 140.7884242, 'B', '自然', '栗駒山（くりこまやま）は、山体が宮城県、秋田県、岩手県の三県にまたがる山。'),
    ('泉ヶ岳', null, '宮城県', '仙台市', 38.4115286, 140.7100181, 'B', '自然', '泉ヶ岳（いずみがたけ）は、宮城県仙台市泉区の北西部に位置する標高1175メートルの山である（三角点は1172.18メートル、北緯38度24分41.7562秒 東経140度42分34.9199秒）。'),
    ('仙台市八木山動物公園', null, '宮城県', '仙台市', 38.2457227, 140.8456364, 'B', 'その他', '仙台市八木山動物公園（せんだいしやぎやまどうぶつこうえん）は、宮城県仙台市太白区にある仙台市立の動物園。'),
    ('仙台サンプラザホール', null, '宮城県', '仙台市', 38.257724, 140.8940725, 'B', 'その他', '仙台サンプラザ（せんだいサンプラザ）は、宮城県仙台市宮城野区榴岡にある、ホテルやホールからなる複合施設である。'),
    ('宮城県民会館', null, '宮城県', '仙台市', 38.2660298, 140.8678871, 'B', 'その他', '宮城県民会館（みやぎけんみんかいかん）は、宮城県仙台市青葉区国分町三丁目にあるコンサートホールと会議室等の文化施設である。'),
    ('宮城県美術館', null, '宮城県', '仙台市', 38.2627014, 140.8548373, 'B', '美術館博物館', '宮城県美術館（みやぎけんびじゅつかん）は、宮城県仙台市青葉区川内元支倉にある宮城県立の美術館である。'),
    ('大崎八幡宮', null, '宮城県', '仙台市', 38.2717221, 140.8449233, 'B', '神社仏閣', '大崎八幡宮（おおさきはちまんぐう）は、宮城県仙台市青葉区八幡にある神社である。'),
    ('竹駒神社', null, '宮城県', '岩沼市', 38.9230315, 141.1317109, 'B', '神社仏閣', '竹駒神社（たけこまじんじゃ）は、宮城県岩沼市中心部にある稲荷神社である。'),
    ('宮城県総合運動公園', null, '宮城県', '利府町', 38.3355587, 140.9548406, 'B', 'その他', '宮城県総合運動公園（みやぎけん そうごううんどうこうえん）は、宮城県宮城郡利府町にある運動公園である。'),
    ('勾当台公園', null, '宮城県', '仙台市', 38.2672292, 140.8714253, 'B', 'その他', '勾当台公園（こうとうだいこうえん）は、宮城県仙台市青葉区本町および国分町にある都市公園である。'),
    ('遠刈田温泉', null, '宮城県', '蔵王町', 38.113246, 140.53776, 'B', '温泉', '遠刈田温泉（とおがったおんせん）は、宮城県刈田郡蔵王町（旧国陸奥国、明治以降は磐城国）にある温泉。'),
    ('仙台東照宮', null, '宮城県', '仙台市', 38.2802077, 140.8851044, 'B', '神社仏閣', '仙台東照宮（せんだいとうしょうぐう）は、宮城県仙台市青葉区東照宮にある徳川家康をまつる神社。'),
    ('伊豆沼', null, '宮城県', '登米市', 38.7169501, 141.1237156, 'B', '自然', '伊豆沼（いずぬま）は、宮城県の登米市及び栗原市にまたがる沼である。'),
    ('潟沼', null, '宮城県', '大崎市', 38.733694, 140.7244812, 'B', '温泉', '潟沼（かたぬま）は、宮城県大崎市鳴子温泉にある湖。'),
    ('宮城県図書館', null, '宮城県', '仙台市', 38.3460954, 140.8383842, 'B', 'その他', '宮城県図書館（みやぎけんとしょかん）は、宮城県仙台市泉区紫山一丁目にある県立図書館である。'),
    ('鳥の海', null, '宮城県', '亘理町', 38.0340148, 140.9213823, 'B', 'その他', '鳥の海（とりのうみ）は、宮城県亘理郡亘理町の太平洋岸に位置する内湾状の汽水湖（潟湖）である。'),
    ('仙台市博物館', null, '宮城県', '仙台市', 38.2560506, 140.8567462, 'B', '美術館博物館', '仙台市博物館（せんだいしはくぶつかん）は、宮城県仙台市青葉区川内にある仙台市立の博物館である。'),
    ('国営みちのく杜の湖畔公園', null, '宮城県', '川崎町', 38.2006364, 140.6716407, 'B', 'その他', '国営みちのく杜の湖畔公園（こくえいみちのくもりのこはんこうえん）は、宮城県柴田郡川崎町の釜房ダム湖畔にある国営公園である。'),
    ('網地島', null, '宮城県', '石巻市', 38.2624642, 141.4810547, 'B', '自然', '網地島（あじしま）は、宮城県石巻市の太平洋上に浮かぶ島である。'),
    ('船岡城址公園', null, '宮城県', '柴田町', 38.0563542, 140.7598737, 'B', 'その他', 'または四保館（しほたて）は、宮城県柴田郡柴田町大字船岡字舘山（四保山）にあった日本の城（山城）。'),
    ('チャチャワールドいしこし', null, '宮城県', '登米市', 38.7602533, 141.1717192, 'B', 'その他', 'チャチャワールドいしこしは、宮城県登米市にある遊園地である。'),
    ('東北歴史博物館', null, '宮城県', '多賀城市', 38.2998205, 140.9945221, 'B', '美術館博物館', '東北歴史博物館（とうほくれきしはくぶつかん）は、宮城県多賀城市にある宮城県立の歴史系博物館である。'),
    ('釜房ダム', null, '宮城県', '川崎町', 38.2018084, 140.6727232, 'C', 'その他', '釜房ダム（かまふさダム）は、宮城県柴田郡川崎町大字小野と大字支倉にまたがる、一級河川・名取川水系碁石川に建設されたダムである。'),
    ('万石浦', null, '宮城県', '女川町', 38.423434, 141.3987542, 'C', 'その他', '万石浦（まんごくうら）は、宮城県の石巻市及び牡鹿郡女川町にまたがる内海である。'),
    ('榴岡公園', null, '宮城県', '仙台市', 38.2603144, 140.8946257, 'C', 'その他', '榴岡公園（つつじがおかこうえん）は、宮城県仙台市宮城野区の丘陵地にある都市公園。'),
    ('鳴子ダム', null, '宮城県', '大崎市', 38.7549678, 140.7049001, 'C', 'その他', '鳴子ダム（なるこダム）は、宮城県大崎市、一級河川・北上川水系江合川に建設されたダムである。'),
    ('宮城縣護國神社', null, '宮城県', '仙台市', 38.251485, 140.8562668, 'C', 'その他', '宮城縣護國神社（みやぎけんごこくじんじゃ）は、宮城県仙台市青葉区川内にある神社（護国神社）である。'),
    ('仙台市天文台', null, '宮城県', '仙台市', 38.256951, 140.755257, 'C', 'その他', '仙台市天文台（せんだいしてんもんだい）は、宮城県仙台市青葉区錦ケ丘にある仙台市立の天文台である。'),
    ('地底の森ミュージアム', null, '宮城県', '仙台市', 38.2227753, 140.8725352, 'C', '美術館博物館', '地底の森ミュージアム（ちていのもりミュージアム）は、宮城県仙台市太白区長町南にある博物館である。'),
    ('青根温泉', null, '宮城県', '川崎町', 38.1461515, 140.5368303, 'C', '温泉', '青根温泉（あおねおんせん）は、宮城県柴田郡川崎町（旧国陸奥国、明治以降は陸前国）にある温泉。'),
    ('宮城野原公園総合運動場', null, '宮城県', '仙台市', 38.2578562, 140.9036303, 'C', 'その他', '宮城野原公園総合運動場（みやぎのはらこうえんそうごううんどうじょう）は、宮城県仙台市宮城野区にある運動公園である。'),
    ('あ・ら・伊達な道の駅', null, '宮城県', '大崎市', 38.7076812, 140.8336857, 'C', 'その他', 'あ・ら・伊達な道の駅（あ・ら・だてなみちのえき）は、宮城県大崎市岩出山池月にある国道47号の道の駅である。'),
    ('仙台文学館', null, '宮城県', '仙台市', 38.2964999, 140.8761426, 'C', 'その他', '仙台文学館（せんだいぶんがくかん）は、宮城県仙台市青葉区北根にある仙台市立の文学館・社会教育施設である。'),
    ('薬萊山', null, '宮城県', '加美町', 38.5755602, 140.7052441, 'C', '自然', '薬萊山（やくらいさん）は、宮城県加美郡加美町のほぼ中央、宮城県立自然公園船形連峰に含まれる標高553mの山である。'),
    ('仙台国際センター', null, '宮城県', '仙台市', 38.258464, 140.857457, 'C', 'その他', '仙台国際センター（せんだいこくさいセンター）は、宮城県仙台市青葉区にあるコンベンションセンター、および、国際交流施設である。'),
    ('道の駅上品の郷', null, '宮城県', '石巻市', 38.5008476, 141.2946215, 'C', 'その他', '道の駅上品の郷（みちのえき じょうぼんのさと）は、宮城県石巻市にある国道45号の道の駅である。'),
    ('化女沼', null, '宮城県', '大崎市', 38.6327553, 140.9566384, 'C', 'その他', '化女沼ダム（けじょぬまダム）は、宮城県大崎市にある宮城県土木部河川課・大崎地方ダム総合事務所が管理する県営ダム。'),
    ('石巻漁港', null, '宮城県', '石巻市', 38.4106391, 141.3343639, 'C', 'その他', '石巻漁港（いしのまきぎょこう）は、宮城県石巻市魚町にある特定第3種漁港である。'),
    ('シーパルピア女川', null, '宮城県', '女川町', 38.4462104, 141.4457989, 'C', 'その他', 'シーパルピア女川（シーパルピアおながわ）は、宮城県牡鹿郡女川町女川に所在するテナント型商店街である。'),
    ('唐桑半島', null, '宮城県', null, 38.8764648, 141.6589845, 'C', '自然', '唐桑半島（からくわはんとう）は、宮城県の北東端にある半島である。'),
    ('七北田公園', null, '宮城県', '仙台市', 38.3190141, 140.8797351, 'C', 'その他', '七北田公園（ななきたこうえん）は、宮城県仙台市泉区泉中央の南側、七北田川沿いにある都市公園である。'),
    ('青葉山公園', null, '宮城県', '仙台市', 38.2573522, 140.8573642, 'C', 'その他', '青葉山公園（あおばやまこうえん）は、宮城県仙台市青葉区にある都市公園である。'),
    ('女川温泉ゆぽっぽ', null, '宮城県', '女川町', 38.4468865, 141.4440051, 'C', '温泉', '女川温泉ゆぽっぽ（おながわおんせんゆぽっぽ）は、宮城県牡鹿郡女川町女川2丁目にある女川町営の温泉である。'),
    ('加護坊山', null, '宮城県', '大崎市', 38.5918033, 141.1061457, 'C', '自然', '加護坊山（かごぼうやま）は、宮城県大崎市の篦岳丘陵にある標高223.2mの山である。'),
